import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
const NEEDS_HUMAN_INPUT = /needs\s+human\s+input/i;
/** A field line whose label ends before the colon, e.g. `- **Retention**:` (value, if any, follows the colon). */
const EMPTY_FIELD_LABEL_COLON = /^\s*[-*]\s*\*\*[^*]+\*\*.*:\s*$/;
/** A field line whose colon sits inside the bold markers, e.g. `- **Retention:**` with nothing after it. */
const EMPTY_FIELD_COLON_IN_LABEL = /^\s*[-*]\s*\*\*[^*]+:\*\*\s*$/;

function indentOf(line: string): number {
  return line.match(/^\s*/)?.[0]?.length ?? 0;
}

/** Collects the indented continuation lines that sit below `lines[index]` (its "answer block"), stopping at the next line of equal-or-lesser indentation. Blank lines in between are kept. */
function collectNestedBlock(lines: string[], index: number): string {
  const indent = indentOf(lines[index]);
  const collected: string[] = [];
  for (let i = index + 1; i < lines.length; i += 1) {
    const line = lines[i];
    if (line.trim() === '') {
      collected.push(line);
      continue;
    }
    if (indentOf(line) <= indent) break;
    collected.push(line);
  }
  return collected.join('\n');
}

function hasNestedContentBelow(lines: string[], index: number): boolean {
  return collectNestedBlock(lines, index).trim() !== '';
}

/** Field lines that look unanswered on their own line, but whose value actually sits in an indented block below (nested bullets, a table, a paragraph) are not unanswered. */
function findEmptyFieldLines(body: string): string[] {
  const lines = body.split(/\r?\n/);
  const empty: string[] = [];
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const isCandidate =
      EMPTY_FIELD_LABEL_COLON.test(line) || EMPTY_FIELD_COLON_IN_LABEL.test(line);
    if (isCandidate && !hasNestedContentBelow(lines, i)) {
      empty.push(line);
    }
  }
  return empty;
}

interface Section {
  heading: string;
  body: string;
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

function extractTier(body: string): RiskTier | null {
  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
  const lines = body.split(/\r?\n/);
  const fieldIndex = lines.findIndex(
    (l) => /^\s*[-*]\s*\*\*tier:?\*\*/i.test(l) || /^\s*[-*]\s*tier\b/i.test(l)
  );
  let haystacks: string[];
  if (fieldIndex === -1) {
    haystacks = [body];
  } else {
    // The tier value may sit on the field line itself, or in an indented block below it.
    const fieldText = hasNestedContentBelow(lines, fieldIndex)
      ? `${lines[fieldIndex]}\n${collectNestedBlock(lines, fieldIndex)}`
      : lines[fieldIndex];
    haystacks = [fieldText];
  }
  for (const text of haystacks) {
    // Skip the template's enum hint "(prohibited / high / limited / minimal)".
    const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
    const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      // Ambiguous mention; prefer the value after a colon on the field line.
      const afterColon = cleaned.split(':').slice(1).join(':');
      const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
      if (inValue.length === 1) return inValue[0];
    }
  }
  return null;
}

function answeredText(body: string): string {
  const empty = new Set(findEmptyFieldLines(body));
  return body
    .split(/\r?\n/)
    .filter((l) => !empty.has(l))
    .join('\n')
    .trim();
}

